const pid_t P2 = 1;
const pid_t P3 = 2;
const pid_t P4 = 3;
const pid_t P5 = 4;

// Type of partition
typedef struct {
    rid_t cpu_id;
    rid_t rq_id;
    time_t period;
    int wind_num;
    int wind_idx;
} partition_t;

// Partition list
const partition_t partition[Partitions] = {
    {CPU1, CPU1_Q1_1, 25000, 1, 0},
    {CPU1, CPU1_Q2_1, 25000, 1, 1},
    {CPU2, CPU2_Q1, 25000, 1, 2},
    {CPU3, CPU3_Q1, 25000, 1, 3},
    {CPU2, CPU2_Q2, 25000, 1, 4}
};

// Type of partition window
typedef struct {
    time_t offset;
    time_t duration;
} partition_window_t;

const int TotalWindowsNum = 5;    // Tatal number of partition windows within one major time frame
const partition_window_t partition_windows[TotalWindowsNum] = {
