/* Global functions */
void _enque1(rid_t rid, tid_t tid, int start, policy_t policy){
    if(policy == FIFO)
        rq[rid].list[rq[rid].len++] = tid;
    if(policy == FP){
        tid_t tmp;
        rq[rid].list[rq[rid].len++] = tid;
        if (rq[rid].len > 1){
            int i = rq[rid].len - 1;
            while(i > start && cprio[rq[rid].list[i]] < cprio[rq[rid].list[i - 1]]){
                tmp = rq[rid].list[i - 1];
                rq[rid].list[i - 1] = rq[rid].list[i];
                rq[rid].list[i] = tmp;
                i--;
            }
        }
    }
}

void _deque1(rid_t rid){
    int[1, Tasks] i;

    for(i = 1; i < rq[rid].len; i++) {
      rq[rid].list[i - 1] = rq[rid].list[i];
    }

    rq[rid].list[rq[rid].len - 1] = 0;
    rq[rid].len--;
}

tid_t _front(rid_t rid){
    return rq[rid].list[0];
}

void sortQueue(rid_t rid, int start) {
    int[0, MaxTasks] i, j;
    tid_t target;

    for(i = start + 1; i < rq[rid].len; i++) {
        j = i;
        target = rq[rid].list[i];
        while(j > start && cprio[target] < cprio[rq[rid].list[j -1]]) {
            rq[rid].list[j] = rq[rid].list[j -1];
            j--;
        }
        rq[rid].list[j] = target;
    }
}

void _enque2(swpid_t sid, vlid_t vid){
    if(swq[sid].len < MaxMsgs)
        swq[sid].list[swq[sid].len++] = vid;
    else
        msgErr = true;
}

void _deque2(swpid_t sid){
    int[1, MaxMsgs] i;

    for(i = 1; i < swq[sid].len; i++) {
      swq[sid].list[i - 1] = swq[sid].list[i];
    }

    swq[sid].list[swq[sid].len - 1] = NVL;
    swq[sid].len--;
}

void _enque3(esid_t eid, vlid_t vid){
    if(esq[eid].len < MaxMsgs)
        esq[eid].list[esq[eid].len++] = vid;
    else
        msgErr = true;
}

void _deque3(esid_t eid){
    int[1, MaxMsgs] i;

    for(i = 1; i < esq[eid].len; i++) {
      esq[eid].list[i - 1] = esq[eid].list[i];
    }

    esq[eid].list[esq[eid].len - 1] = NVL;
    esq[eid].len--;
}

void _enque4(msgid_t msgid){
    if(msgprioq[msg[msgid].msgprio].len < MaxMsgs)
        msgprioq[msg[msgid].msgprio].list[msgprioq[msg[msgid].msgprio].len++] = msgid;
    else
        msgErr = true;
}

void _deque4(msgid_t msgid){
    int[1,MaxMsgs] i;

    for(i = 1; i < msgprioq[msg[msgid].msgprio].len; i++){
        msgprioq[msg[msgid].msgprio].list[i - 1] = msgprioq[msg[msgid].msgprio].list[i];
    }

    msgprioq[msg[msgid].msgprio].list[msgprioq[msg[msgid].msgprio].len - 1] = 0;
    msgprioq[msg[msgid].msgprio].len--;
}

