bool avail(rid_t rid) { return resstat[muxid(rid)].occupied == 0; }

void lock(rid_t rid) {
    resstat[muxid(rid)].occupied = 1;
    resstat[muxid(rid)].owner = tid;

    // Raise priority
    if(Ceiling[muxid(rid)] < cprio[tid])
        cprio[tid] = Ceiling[muxid(rid)];
}

void unlock(rid_t rid) {
    resstat[muxid(rid)].occupied = 0;
    resstat[muxid(rid)].owner = 0;

    // Restore priority
    cprio[tid] = defPrio();
}

void wait(rid_t rid) {
    //Add to waiting queue
    resstat[muxid(rid)].waiting++;
    enque(rid, tid, 0, FP);
}

void signal(rid_t rid) {
    // The first task blocked on rid are resumed
    if(resstat[muxid(rid)].waiting > 0) {
        //enque(rqID(), front(rid), 1, FP);
        deque(rid);
        resstat[muxid(rid)].waiting--;
    }
}

bool isWaken(rid_t rid) { return (front(rid) == tid); }

