void enque(msgid_t msgid){
    msgid_t temp;
    if(msgprioq[0].len < MaxMsgs)
        msgprioq[0].list[msgprioq[0].len++] = msgid;
    else
        msgErr = true;

    if(msgprioq[0].len > 1){
        int i = msgprioq[0].len - 1;
        while(i > 0 && msg[msgprioq[0].list[i]].msgprio < msg[msgprioq[0].list[i - 1]].msgprio){
            temp = msgprioq[0].list[i - 1];
            msgprioq[0].list[i - 1] = msgprioq[0].list[i];
            msgprioq[0].list[i] = temp;
            i--;
        }
    }   
}

void deque(){
    int[1, MaxMsgs] i;

    for(i = 1; i < msgprioq[0].len; i++){
        msgprioq[0].list[i - 1] = msgprioq[0].list[i];
    }

    msgprioq[0].list[msgprioq[0].len - 1] = 0;
    msgprioq[0].len--;
}

