void udpSend(msgid_t msgid)
{
    portid_t p = vlink[msg[msgid].vl].src;

    if(portMode(p) == QUEUING){
        if(portbuf[p] < pcapacity(p))
            portbuf[p]++;
        else
            _setMsgErr(msgid);
    }
    if(portMode(p) == SAMPLING)
        portbuf[p] = 1;
}

