void allEnque(vlid_t v)
{
    int[0, MaxFTSize] i;
    portid_t dstPort = NUL;

    for(i = 0; i < vlink[v].ft_size; i++)
        if(vlink[v].ft[i].src == port && !portDisabled(vlink[v].ft[i].dst)){
            dstPort = vlink[v].ft[i].dst;
            if(isTerminal(dstPort)){
                // Forwarded to an ES node directly
                if(portMode(dstPort) == QUEUING){
                    if(portbuf[dstPort] < pcapacity(dstPort))
                        portbuf[dstPort]++;
                    else
                        _setPortErr(dstPort);
                }
                if(portMode(dstPort) == SAMPLING){
                    portbuf[dstPort] = 1;
                    port_clock[dstPort] = 0;
                }
            }else if(isSwitch(dstPort)){
                // Forwarded to a switch
                enque(dstPort, v);
            }
        }
}

