void vlSend(vlid_t v)
{
    int[0, MaxFTSize] i;
    portid_t dstPort = NUL;

    //portbuf[vlink[v].src]--;

    for(i = 0; i < vlink[v].ft_size; i++)
        if(vlink[v].ft[i].src == espid(eid)){
            dstPort = vlink[v].ft[i].dst;
            if(!isSwitch(dstPort))
                // Connected to an ES node directly, not allowed, and do nothing.
                ;
            else
                // Connected to a switch
                if(!portDisabled(dstPort))
                    enque(dstPort, v);
        }
}

